/bin/bash -lc "python3 - <<'PY'
import os, json, requests, urllib.parse
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
ids=['toolshed.g2.bx.psu.edu/repos/iuc/rgrnastar/rna_star/2.7.11b+galaxy1','toolshed.g2.bx.psu.edu/repos/iuc/arriba/arriba/2.5.1+galaxy0','toolshed.g2.bx.psu.edu/repos/iuc/pizzly/pizzly/0.37.3.1']
terms=['hg38','hg19','GRCh38','GRCh37','Homo sapiens','Human','gencode']

def walk(x,path=''):
    if isinstance(x,dict):
        # options lists
        if 'options' in x and isinstance(x.get('options'), list):
            hits=[]
            for opt in x['options']:
                s=json.dumps(opt)
                if any(t.lower() in s.lower() for t in terms): hits.append(opt)
            if hits:
                print('\\nPATH', path, 'name', x.get('name'), 'label', x.get('label'), 'hits', len(hits))
                for h in hits[:50]: print(h)
        for k,v in x.items(): walk(v, path+'/'+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v, path+f'[{i}]')
for tid in ids:
    print('===', tid)
    r=requests.get(url+'/api/tools/'+urllib.parse.quote(tid,safe=''), params={'io_details':'true','key':key}, timeout=120)
    r.raise_for_status(); data=r.json(); walk(data)
PY"

